mapper.sql:
WHERE sgg_cd_nm = #{sggNm}
  AND stdg_cd_nm = #{bjdongNm}
  AND is_deleted = false
AND plot_se_cd_nm = #{platGbCd}
AND mn_lotno = #{bun}
AND sub_lotno = #{ji}

WHERE b.is_deleted = false
AND b.sgg_cd_nm = #{sggNm}
AND b.stdg_cd_nm = #{bjdongNm}
AND b.use_aprv_ymd >= #{useApprovalDateMin}
AND b.use_aprv_ymd <= #{useApprovalDateMax}

    AND (



                1 = 0


                (
                b.mn_usg_cd_nm IN
                #{name}
                AND

                    b.grnd_nofl >= #{f.apartmentMinFloors}
                    b.grnd_nofl < #{f.apartmentMinFloors}


                    AND b.hh_cnt IS NOT NULL AND b.hh_cnt != 0
                    AND (b.gfa / b.hh_cnt) >= #{f.areaMin}
                    AND (b.gfa / b.hh_cnt) <= #{f.areaMax}

                )


                (
                b.mn_usg_cd_nm IN
                #{name}
                AND b.gfa >= #{f.areaMin}
                AND b.gfa <= #{f.areaMax}
                )



    )


    AND EXISTS (
        SELECT 1 FROM investment_result ir
        WHERE ir.building_id = b.bdrg_sn AND ir.grade = #{grade} AND ir.is_deleted = false
    )
